    ('fe2d7984-777d-44c9-809c-372edbad7362', ARRAY['단어 > 단어의 의미 > 의미 관계 - 동음이의어·다의어']::TEXT[],
      ARRAY['단어 > 단어의 의미 > 혼합']::TEXT[], NULL),
    -- 천재(노미숙) 중2-1 평가문제집 3-(1) 점검·조정하며 글 읽기 (평가문제집) 3번 — 문맥의 빈칸에 알맞은 낱말을 고르는 어휘 문항
    ('fe9f9f93-ee39-417f-bcea-ef47429ebfa0', ARRAY['단어 > 단어의 의미 > 단어의 의미 유형']::TEXT[],
      ARRAY['단어 > 단어의 의미 > 혼합']::TEXT[], NULL),
    -- 천재(노미숙) 중1-2 평가문제집 3-(1) 품사의 종류와 특성 (평가문제집) 81번 — 품사가 아니라 활용형의 기본형을 물음
    ('fecd49be-99fc-41fc-a0ef-edca51e1ba9b', ARRAY['단어 > 품사 > 동사']::TEXT[],
      ARRAY['단어 > 용언 > 용언의 활용']::TEXT[], NULL),
    -- 2023 광희중학교 중2 2학기 중간 19번 — 창제 배경·목적과 음소 문자의 특성을 두루 물음
    ('fef5faf8-9e18-5b39-85cc-ffaddaa07906', ARRAY['국어의 역사 > 훈민정음 > 훈민정음 창제 이전 표기 방식']::TEXT[],
      ARRAY['국어의 역사 > 훈민정음 > 혼합']::TEXT[], NULL),
    -- 2025 숭실고등학교 고1 2학기 중간 5번 — 의미의 갈래가 아니라 낱말의 뜻풀이를 물음
    ('ff01ed9a-b79e-4844-af6d-f9d04d468bbc', ARRAY['단어 > 단어의 의미 > 단어의 의미 유형']::TEXT[],
      ARRAY['단어 > 단어의 의미 > 혼합']::TEXT[], NULL),
    -- 비상(박현숙) 중1-2 평가문제집 2-(2) 어휘의 양상과 쓰임 (평가문제집) 17번 — 한자어에 익숙하지 않아 생기는 이해 문제
    ('ff0247d4-efc5-4954-a618-3a3953970795', ARRAY['단어 > 어휘 체계와 양상 > 유행어·은어·전문어']::TEXT[],
      ARRAY['단어 > 어휘 체계와 양상 > 고유어·한자어·외래어']::TEXT[], NULL),
    -- 2024 무학중학교 중1 2학기 중간 9번 — 두 빈칸에 해당하는 관형사와 부사를 함께 물음
    ('ff69f07a-06c7-4602-96d6-56a64f3c5658', ARRAY['단어 > 품사 > 관형사']::TEXT[],
      ARRAY['단어 > 품사 > 관형사', '단어 > 품사 > 부사']::TEXT[], NULL),
    -- 2023 행당중학교 중2 2학기 중간 7번 — 한글과 알파벳의 일반적 특성을 비교함
    ('ff6dea3c-a595-5a79-ac27-2c60d5195413', ARRAY['국어의 역사 > 훈민정음 > 훈민정음 운용 원리']::TEXT[],
      ARRAY['국어의 역사 > 훈민정음 > 혼합']::TEXT[], NULL),
    -- 천재(노미숙) 중1-2 평가문제집 3-(1) 품사의 종류와 특성 (평가문제집) 56번 — 관형사의 사용 여부만 직접 묻음
    ('ff99801c-50db-45f1-8808-cb052eff34c5', ARRAY['단어 > 품사 > 관형사', '단어 > 품사 > 부사']::TEXT[],
      ARRAY['단어 > 품사 > 관형사']::TEXT[], NULL),
    -- 2025 잠실고등학교 고1 1학기 기말 15번 — 동음 관계 자체가 아니라 문맥에 맞는 뜻을 물음
    ('ffa2ce5d-95b3-45e3-9b21-6937117b4bf4', ARRAY['단어 > 단어의 의미 > 의미 관계 - 동음이의어·다의어']::TEXT[],
      ARRAY['단어 > 단어의 의미 > 혼합']::TEXT[], NULL),
    -- 2023 광희중학교 중2 1학기 중간 23번 — 담화의 구성 요소와 맥락을 함께 판단함
    ('ffb68d93-810c-53a1-832f-30067c1dac76', ARRAY['담화 > 담화 구성 요소와 기능']::TEXT[],
      ARRAY['담화 > 담화 구성 요소와 기능', '담화 > 담화의 맥락']::TEXT[], NULL),
    -- 2022 행당중학교 중3 1학기 기말 10번 — 남북한 표기 비교이므로 별도 맞춤법 태그 제외
    ('ffda93eb-10d1-5adb-a29c-481ac57c3eec', ARRAY['남북한 언어 > 남북한 표기와 맞춤법 차이', '어문 규정 > 한글 맞춤법']::TEXT[],
      ARRAY['남북한 언어 > 남북한 표기와 맞춤법 차이']::TEXT[], NULL);

  SELECT count(*) INTO v FROM audit_fix;
  IF v <> 1393 THEN RAISE EXCEPTION '목록 수가 다르다: %', v; END IF;

  -- 순서와 상관없이 같은 값이면 같은 것으로 본다(배열 정렬 비교)
  SELECT count(*) INTO v FROM audit_fix WHERE new_area IS NOT NULL;
  IF v <> 37 THEN RAISE EXCEPTION '영역을 옮길 문항 수가 다르다: %', v; END IF;

  UPDATE exam.problems p
     SET grammar_paths = f.new_paths,
         area_path = COALESCE(f.new_area, p.area_path)
    FROM audit_fix f
   WHERE p.id = f.id
     AND (SELECT array_agg(x ORDER BY x) FROM unnest(p.grammar_paths) x)
         IS NOT DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(f.old_paths) x)
     AND (f.new_area IS NULL OR p.area_path = ARRAY['화법과 언어', '언어']::TEXT[]);
  GET DIAGNOSTICS v_changed = ROW_COUNT;

  SELECT count(*) INTO v_already FROM exam.problems p JOIN audit_fix f ON f.id = p.id
   WHERE (SELECT array_agg(x ORDER BY x) FROM unnest(p.grammar_paths) x)
         IS NOT DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(f.new_paths) x);
  SELECT count(*) INTO v FROM audit_fix f WHERE NOT EXISTS (SELECT 1 FROM exam.problems p WHERE p.id = f.id);
  RAISE NOTICE '바꿈 %건 · 새 값인 문항(이번 포함) %건 · 없는 문항 %건 / 목록 %건', v_changed, v_already, v, 1393;

  FOR r IN
    SELECT p.id, p.grammar_paths FROM exam.problems p JOIN audit_fix f ON f.id = p.id
     WHERE (SELECT array_agg(x ORDER BY x) FROM unnest(p.grammar_paths) x)
           IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(f.new_paths) x)
  LOOP
    RAISE NOTICE '손으로 고친 값이 있어 건너뜀: % %', r.id, r.grammar_paths;
  END LOOP;

  -- -------------------------------------------
  -- 검증 — 규칙이 표 전체에서 지켜지는가
  -- -------------------------------------------
  CREATE TEMP TABLE tag_parts ON COMMIT DROP AS
    SELECT p.id, g,
           CASE WHEN g LIKE '% > % > %' THEN split_part(g, ' > ', 1) || ' > ' || split_part(g, ' > ', 2)
                WHEN split_part(g, ' > ', 1) IN ('담화', '어문 규정', '남북한 언어') AND g LIKE '% > %'
                  THEN split_part(g, ' > ', 1) END AS parent
      FROM exam.problems p, unnest(p.grammar_paths) g;

  SELECT count(*) INTO v_bad FROM exam.problems WHERE cardinality(grammar_paths) > 5;
  IF v_bad > 0 THEN RAISE EXCEPTION '검증 실패: 태그 5개를 넘은 문항 %건', v_bad; END IF;

  SELECT count(DISTINCT id) INTO v FROM tag_parts WHERE parent IS NULL;
  RAISE NOTICE '검증: 중간 마디 태그가 남은 문항 %건 (기대 0)', v;
  v_bad := v;

  SELECT count(*) INTO v FROM (
    SELECT id, parent FROM tag_parts WHERE parent IS NOT NULL GROUP BY id, parent
    HAVING (count(*) FILTER (WHERE g NOT LIKE '% > 혼합') >= 3)
        OR (bool_or(g LIKE '% > 혼합') AND count(*) > 1)
  ) s;
  RAISE NOTICE '검증: 한 가지에 잎 셋 이상(또는 혼합+잎)인 문항 %건 (기대 0)', v;
  v_bad := v_bad + v;

  SELECT count(*) INTO v FROM (
    SELECT p.id,
           sum(CASE WHEN g LIKE '% > 혼합' THEN 3 ELSE 1 END) AS concepts,
           count(*) FILTER (WHERE g NOT LIKE '% > 혼합') AS specific
      FROM exam.problems p, unnest(p.grammar_paths) g
     WHERE g LIKE '음운 > 음운 교체 > %' OR g LIKE '음운 > 음운 축약·탈락·첨가 > %'
     GROUP BY p.id
  ) s WHERE concepts >= 3 AND specific > 0;
  RAISE NOTICE '검증: 음운 변동 종합인데 개별 칸이 남은 문항 %건 (기대 0)', v;
  v_bad := v_bad + v;

  SELECT count(*) INTO v FROM exam.problems p
   WHERE EXISTS (SELECT 1 FROM unnest(p.grammar_paths) g WHERE g LIKE '국어의 역사 > 중세 국어 > %')
     AND EXISTS (SELECT 1 FROM unnest(p.grammar_paths) g WHERE g NOT LIKE '국어의 역사 > 중세 국어 > %');
  RAISE NOTICE '검증: 중세 국어와 다른 태그가 섞인 문항 %건 (기대 0)', v;
  v_bad := v_bad + v;

  -- 영역이 '언어' 인데 문법 태그가 빈 문항은 없다(2026-11-06 불변식)
  SELECT count(*) INTO v FROM exam.problems
   WHERE area_path[1] = '화법과 언어' AND area_path[2] = '언어' AND cardinality(grammar_paths) = 0;
  RAISE NOTICE '검증: 언어 영역인데 태그가 빈 문항 %건 (기대 0)', v;
  v_bad := v_bad + v;

  SELECT count(*) INTO v FROM exam.problems p JOIN audit_fix f ON f.id = p.id
   WHERE f.new_area IS NOT NULL AND p.area_path IS DISTINCT FROM f.new_area;
  RAISE NOTICE '검증: 영역을 옮기기로 한 문항 중 옮겨지지 않은 것 %건 (기대 0)', v;

  -- 남북한 언어 문항에는 음운 태그가 없다(sql/108)
  SELECT count(*) INTO v FROM exam.problems p
   WHERE EXISTS (SELECT 1 FROM unnest(p.grammar_paths) g WHERE g LIKE '남북한 언어 > %')
     AND EXISTS (SELECT 1 FROM unnest(p.grammar_paths) g WHERE g LIKE '음운 > %');
  RAISE NOTICE '검증: 남북한 언어와 음운 태그가 함께 붙은 문항 %건 (기대 0)', v;
  v_bad := v_bad + v;

  IF v_changed > 0 AND v_bad > 0 THEN
    RAISE EXCEPTION '검증 실패: 규칙을 어긴 문항이 %건 남았다 — 목록에 빠진 문항이 있다', v_bad;
  END IF;

  FOR r IN SELECT g, count(*) n FROM exam.problems, unnest(grammar_paths) g
            WHERE g LIKE '단어 > 품사 > %' OR g LIKE '단어 > 단어의 의미 > %' OR g LIKE '문장 > 문장의 짜임 > %'
            GROUP BY 1 ORDER BY 1 LOOP
    RAISE NOTICE '  %건 : %', r.n, r.g;
  END LOOP;
END
$audit$;
